"""Read-only model-static slice exposed to builder-defined LLM tools."""

from __future__ import annotations

from typing import Any, Optional

from pydantic import BaseModel, ConfigDict, Field

from rasa.core.information_retrieval import InformationRetrieval
from rasa.mantle.model_archive.bootstrap import ModelBootstrap


class ToolModelContext(BaseModel):
    """Model-static data available to in-process ``@tool`` functions.

    Built once per turn from
    :class:`~rasa.mantle.model_archive.bootstrap.ModelBootstrap` and attached
    to :class:`~rasa.mantle.state.tracker_handle.TrackerHandle`.
    Tools access it via :attr:`~rasa.mantle.tools.decorator.ToolContext.model`.
    """

    # ``arbitrary_types_allowed`` covers ``references_index`` — an
    # ``InformationRetrieval`` retriever, which is not a pydantic type.
    model_config = ConfigDict(frozen=True, arbitrary_types_allowed=True)

    llm_config: dict[str, Any] = Field(default_factory=dict)
    """Project LLM settings from ``integration.yml`` (same as the orchestrator)."""

    references_index: Optional[InformationRetrieval] = None
    """Local FAISS index over the packaged ``references/`` files, or ``None`` when
    the project ships no reference files. The ``search_knowledge`` tool queries it."""

    @classmethod
    def from_bootstrap(cls, bootstrap: ModelBootstrap) -> ToolModelContext:
        """Build a tool-facing slice from loaded model bootstrap data."""
        return cls(
            llm_config=dict(bootstrap.llm),
            references_index=bootstrap.references_index,
        )
